import json,subprocess,copy
im=json.load(open('/tmp/snap.json'))
def getw(im,s,c):return int(im['banks'][s][c//2],16)
def setw(im,s,c,w):im['banks'][s][c//2]=f'{w:064x}'
def field(im,s,c,o,n):
 w=getw(im,s,c);b=128 if c&1 else 0;return (w>>(b+o))&((1<<n)-1)
def setfield(im,s,c,o,n,v):
 w=getw(im,s,c);b=128 if c&1 else 0;mask=((1<<n)-1)<<(b+o);w=(w&~mask)|((v&((1<<n)-1))<<(b+o));setw(im,s,c,w)
NODES=walk_nodes(im)
def find(pred):
 for s,c,t in NODES:
  if pred(s,c,t):return s,c,t
 return None

def walk_nodes(im):
 out=[];seen=set()
 def rec(loc):
  s,c=loc
  if (s,c) in seen:return
  seen.add((s,c));t=field(im,s,c,0,3)
  if not 1<=t<=5:return
  out.append((s,c,t))
  if t in (1,2):
   slots=2 if t==1 else 6
   for i in range(slots):
    raw=field(im,s,c,63+32*i,32);st=(raw>>6)&15
    if st<=10:rec((st,(raw>>10)&0x3fffff))
  elif t==3:
   for i in range(3):
    raw=field(im,s,c,153+32*i,32);st=(raw>>6)&15
    if st<=10:rec((st,(raw>>10)&0x3fffff))
   bm=field(im,s,c,63,64);base=field(im,s,c,127,22);bs=field(im,s,c,149,4)
   for k in range(64):
    if bm>>k&1:
     ord=bin(bm&((1<<k)-1)).count('1');rec((bs,base+2*ord))
 if im['root'] is not None:rec(tuple(im['root']))
 for f in im['front16']+im['front64']:rec((f[1],f[2]))
 return out

